-- ============================================================
-- seed_92125_zuru_engineering.sql
-- 92125 一窝蛋 (ZURU) 工程放产资料 seed
-- 来源: 排模表/排模图/外购件清单 (2025 工程放产资料)
-- 内容: 工模表26 + 塑胶物料资料150 + 物料资料(外购件)90
--       + 款号总表6 + 款号物料明细表(BOM)270
-- 幂等: 重跑先按相同条件删除旧数据再插入
-- ============================================================
SET NOCOUNT ON;
-- 款号物料明细表.工模编号 原由非编号脚本 migrate_semi_finished_common_materials.sql 添加；
-- run-db.ps1 按编号自动枚举不含 migrate_*，此处自包含补齐（幂等，已存在则跳过）。
-- 独立一批（GO 分隔）：整批编译期会校验列存在性，ALTER 须先执行完，后面 INSERT 才能引用新列。
IF OBJECT_ID(N'[款号物料明细表]', N'U') IS NOT NULL
   AND COL_LENGTH(N'[款号物料明细表]', N'工模编号') IS NULL
BEGIN
  ALTER TABLE [款号物料明细表] ADD [工模编号] nvarchar(100) NULL;
END;
GO
BEGIN TRANSACTION;
-- ZURU 客户编号按本库客户资料查找(各库编号可能不同, 避免硬编码 FK 冲突), 找不到则中止
DECLARE @ZuruCustNo nvarchar(20);
SELECT TOP 1 @ZuruCustNo = 客户编号 FROM 客户资料 WHERE 客户名称 = N'ZURU';
IF @ZuruCustNo IS NULL
BEGIN
  -- 全新空库（云端首装）尚无客户档案：跳过本 seed 不算错误；
  -- 将来库内有 ZURU 客户后，重跑部署会自动补种（本脚本幂等）。
  PRINT N'客户资料中无 ZURU，跳过 92125 工程资料 seed';
  ROLLBACK TRANSACTION;
  RETURN;
END
-- 库内已有 ZURU 工程数据（如历史数据恢复后）：seed 只负责首装铺底。
-- 下面的 DELETE 会撞 生产BOM物料清单 等真实业务数据的 FK 引用（部署实录 exit 139），
-- 且清空重建会覆盖用户改过的行，故直接跳过。
IF EXISTS (SELECT 1 FROM [工模表] WHERE [客户] = 'ZURU')
BEGIN
  PRINT N'已存在 ZURU 工程数据，跳过 92125 seed（不清空重建）';
  ROLLBACK TRANSACTION;
  RETURN;
END
-- ----- 工模表: 26 行 -----
DELETE FROM [工模表] WHERE 客户 = 'ZURU';
SET IDENTITY_INSERT [工模表] ON;
8:2', NULL, NULL, N'模架:300*350*412mm', N'ZURU', 4.0);
SET IDENTITY_INSERT [工模表] OFF;
