8:2', 28.0, 18.0, 4.5, 4.0, 4.0, 4.0, 1.0, 35.71, 3600.0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'14A');
8:2', 28.0, 18.0, 4.5, 4.0, 4.0, 4.0, 1.0, 35.71, 3600.0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'14A');
SET IDENTITY_INSERT [塑胶物料资料] OFF;
